package com.durga.spring_rest_api.entity;

import jakarta.persistence.Column;
import jakarta.persistence.Entity;
import jakarta.persistence.GeneratedValue;
import jakarta.persistence.GenerationType;
import jakarta.persistence.Id;
import jakarta.persistence.Table;
import lombok.Getter;
import lombok.NoArgsConstructor;
import lombok.Setter;

/**
 * Product persisted in the {@code products} table.
 */
@Entity
@Table(name="products")
@Setter
@Getter
@NoArgsConstructor
public class Product {
	
	
	/** Identifier generated by the database when the product is persisted. */
	@Id
	@GeneratedValue(strategy = GenerationType.IDENTITY)
	private Long id;
	
	
	/** Product name. */
	private String name;
	
	/** Product category. */
	private String category;
	
	/**
	 * Availability, defaulting to {@code false} for new Java instances.
	 * The wrapper type accepts {@code null} from existing database rows.
	 * The column name retains the existing database spelling for compatibility.
	 */
	@Column(name="is_avialable")
	private Boolean available = false;
	
	/** Product price. */
	private double price;

}
